import re
from collections import defaultdict

def solve(lines):
    # Parse lines, stop at first malformed
    entries = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        if line.startswith('#'):
            continue
        parts = line.split()
        if len(parts) not in (4, 5):
            break  # malformed
        try:
            term = int(parts[0])
            if term < 0:
                break  # malformed
        except ValueError:
            break
        try:
            index = int(parts[1])
            if index <= 0:
                break  # malformed
        except ValueError:
            break
        node = parts[2]
        if not re.match(r'^n[0-9]+$', node):
            break  # malformed
        op = parts[3]
        data = None
        if op == 'APPEND':
            if len(parts) != 5:
                break  # malformed
            data = parts[4]
        elif op in ('VOTE', 'COMMIT', 'LEADER'):
            if len(parts) != 4:
                break  # malformed
        else:
            break  # unknown operation
        entries.append((term, index, node, op, data))

    # Group by index
    index_entries = defaultdict(list)
    for term, index, node, op, data in entries:
        index_entries[index].append((term, index, node, op, data))

    # Process each index
    bad = []  # list of (index, reason)
    ins = []  # list of (index, term)

    # Global vote tracking: (term, node) -> count
    votes = {}
    # First LEADER index per (term, node)
    first_leader = {}

    # For log matching: committed term at each index
    committed_term = {}

    for index in sorted(index_entries.keys()):
        idx_entries = index_entries[index]
        # Skip duplicates: same term, node, op, data
        seen = set()
        unique_entries = []
        for term, idx, node, op, data in idx_entries:
            key = (term, node, op, data)
            if key not in seen:
                seen.add(key)
                unique_entries.append((term, idx, node, op, data))

        # Process each entry in order
        for term, idx, node, op, data in unique_entries:
            if op == 'VOTE':
                if (term, node) in votes:
                    votes[(term, node)] += 1
                    if votes[(term, node)] >= 2:
                        bad.append((idx, 'BAD_DUPLICATE_VOTE'))
                else:
                    votes[(term, node)] = 1
            elif op == 'LEADER':
                if (term, node) in first_leader:
                    bad.append((idx, 'BAD_LEADER_ORDER'))
                else:
                    first_leader[(term, node)] = idx

        # Track APPEND and COMMIT entries
        append_entries = []
        commit_entries = []
        for term, idx, node, op, data in unique_entries:
            if op == 'APPEND':
                append_entries.append((term, node, data))
            elif op == 'COMMIT':
                commit_entries.append((term, node))

        # Check term monotonicity: terms must be non-decreasing within same index
        prev_term = None
        for term, idx, node, op, data in unique_entries:
            if prev_term is not None and term < prev_term:
                bad.append((idx, 'BAD_TERM_REGRESSION'))
            prev_term = term

        # Check conflicts: multiple APPENDs with same term but different data
        term_data = {}
        for term, node, data in append_entries:
            if term in term_data:
                if term_data[term] != data:
                    bad.append((idx, 'BAD_CONFLICT'))
            else:
                term_data[term] = data

        # Determine winning APPEND: highest term, then last in file order
        winning_term = None
        winning_data = None
        for term, node, data in append_entries:
            if winning_term is None or term > winning_term:
                winning_term = term
                winning_data = data

        # Check log matching: if index has committed entry, next index must have entries with term >= committed_term
        if idx in committed_term:
            committed_t = committed_term[idx]
            if idx + 1 in index_entries:
                for term, idx2, node, op, data in index_entries[idx + 1]:
                    if term < committed_t:
                        bad.append((idx + 1, 'BAD_LOG_MATCH'))

        # Check COMMIT validity
        for term, node in commit_entries:
            # Must appear after at least one APPEND at the same index
            has_append = False
            for a_term, a_node, a_data in append_entries:
                if a_term == term:
                    has_append = True
                    break
            if not has_append:
                bad.append((idx, 'BAD_COMMIT_ORDER'))
            # Must have same term as winning APPEND
            if term != winning_term:
                bad.append((idx, 'BAD_COMMIT_ORDER'))

        # Repair: if there are APPENDs but no valid COMMIT
        if append_entries and not commit_entries:
            ins.append((idx, winning_term))

        # Track committed term for log matching
        if commit_entries:
            committed_term[idx] = winning_term

